import type { SidebarsConfig } from "@docusaurus/plugin-content-docs";

// The one place that orders and labels the docs navigation. Page titles come from front matter;
// `label` here only overrides the sidebar text with a task-phrased name. Every page in ../docs
// must be listed here (or sit under deep-dive/evidence, which is autogenerated).
const group = (label: string, slug: string, description: string, items: SidebarsConfig[string]) => ({
  type: "category" as const,
  label,
  collapsed: false,
  link: { type: "generated-index" as const, slug: `/category/${slug}`, description },
  items,
});

const doc = (id: string, label?: string) => ({ type: "doc" as const, id, ...(label ? { label } : {}) });

const sidebars: SidebarsConfig = {
  docs: [
    group("Get started", "get-started", "Run tiny-eye on your machine, send it data, query it, and learn the few concepts behind it.", [
      doc("intro", "What is tiny-eye"),
      doc("getting-started/quickstart", "Quickstart"),
      doc("getting-started/installation", "Install and configure"),
      doc("getting-started/concepts", "Core concepts"),
    ]),
    group(
      "Guides",
      "guides",
      "Worked examples: a demo shop end to end, TQS recipes, sending data from common agents, AI agents over MCP, and dashboards as code.",
      [
        doc("examples/demo-shop", "Run the demo shop"),
        doc("examples/sending-data", "Send data"),
        doc("examples/query-cookbook", "Write queries (cookbook)"),
        doc("examples/dashboards-as-code", "Build dashboards as code"),
        doc("examples/ai-agents-mcp", "Connect an AI agent"),
      ],
    ),
    group("Concepts", "concepts", "How tiny-eye works inside, for engineers: every mechanism, why it is built that way, and what proves it.", [
      doc("deep-dive/architecture"),
      doc("deep-dive/storage-format"),
      doc("deep-dive/write-path"),
      doc("deep-dive/catalog-and-maintenance"),
      doc("deep-dive/query-engine"),
      doc("deep-dive/performance"),
      doc("deep-dive/tqs-reference"),
      doc("deep-dive/api-and-codegen"),
      doc("deep-dive/dashboards-and-ui"),
      doc("deep-dive/configuration"),
      doc("deep-dive/security"),
      doc("deep-dive/operations", "Operate a node"),
      doc("deep-dive/testing-and-evidence"),
      doc("deep-dive/limitations-and-roadmap"),
      {
        type: "category",
        label: "Evidence (generated)",
        link: {
          type: "generated-index",
          slug: "/category/evidence",
          description: "Reports written by make conformance, make e2e, make bench and make bench-s3.",
        },
        items: [{ type: "autogenerated", dirName: "deep-dive/evidence" }],
      },
    ]),
    group("Reference", "reference", "HTTP API, MCP tools and editor grammars.", [
      doc("reference/http-api"),
      doc("reference/mcp-tools"),
      doc("reference/editor-grammars"),
    ]),
  ],
};

export default sidebars;
